package com.meaningfulplushies.packingstation;
import java.util.Locale;
final class PairingProblem {
    static String explain(String raw){
        String message=raw==null?"":raw.trim(),code=message.toUpperCase(Locale.ROOT);
        if(code.contains("NFC_CARD_ALREADY_ASSIGNED"))return "This card is already paired to a different order. Scan the correct card.";
        if(code.contains("NFC_ORDER_ALREADY_PAIRED"))return "This order already has a different card. Check its existing pairing.";
        if(code.contains("NFC_CARD_NOT_PROGRAMMED"))return "This NFC card has not been written yet. Use a prepared card.";
        if(code.contains("NFC_CARD_NOT_FOUND")||code.equals("NFC CARD NOT FOUND."))return "This NFC card was not found. Scan a card generated by this system.";
        if(code.contains("NFC_CARD_VOIDED")||code.contains("CARD IS VOIDED"))return "This NFC card has been cancelled. Use a valid card.";
        if(code.contains("NFC_CERTIFICATE_PENDING"))return "This order's certificate is still syncing. Wait a moment and scan again.";
        if(code.contains("NFC_CERTIFICATE_MISSING"))return "This order has no certificate link yet. Check its details in the fulfilment system.";
        if(code.contains("NFC_CERTIFICATE_SHARED"))return "This certificate link belongs to more than one order. Ask the administrator to check it.";
        if(code.contains("NFC_ORDER_NOT_READY"))return "This order is not ready for card pairing. Check it in the fulfilment system.";
        if(code.contains("SIGN_IN_REQUIRED")||code.contains("WAREHOUSE_ACCESS_REQUIRED")||code.contains("ACTIVE STAFF ACCOUNT"))return "Your staff sign-in has expired or is unavailable. Please sign in again.";
        // Speak the station's short operator messages, never a raw SQL error,
        // internal URL, token or a server diagnostic returned by an exception.
        if(message.length()<=250&&!message.contains("://")&&!message.contains("_")&&
            (code.startsWith("SCAN ")||code.startsWith("ORDER ")||code.startsWith("THIS ")||code.startsWith("THE MATCHING ")||code.startsWith("CHOOSE A CAMERA")||code.startsWith("TABLET STORAGE")||code.startsWith("CARD VERIFICATION")||code.startsWith("CHECK THE CONNECTION")||code.startsWith("A COMPLETE ")||code.startsWith("PAIR ")))return message;
        if(code.contains("TIMEOUT")||code.contains("TIMED OUT")||code.contains("CONNECT")||code.contains("RESOLVE HOST")||code.contains("NETWORK"))return "The connection failed. Check Wi-Fi and try the scan again.";
        return "Pairing could not be confirmed. Check the order and card, then scan again.";
    }
}
